**1. @HttpExchange — the modern default:**

```java
public interface GitHubClient {

    @GetExchange("/users/{username}")
    User getUser(@PathVariable String username);

    @PostExchange("/repos/{owner}/{repo}/issues")
    Issue createIssue(@PathVariable String owner,
                      @PathVariable String repo,
                      @RequestBody IssueRequest req);
}

@Configuration
public class ClientConfig {

    @Bean
    GitHubClient gitHubClient(RestClient.Builder builder) {
        RestClient client = builder
            .baseUrl("https://api.github.com")
            .defaultHeader(HttpHeaders.ACCEPT, "application/vnd.github+json")
            .requestFactory(new JdkClientHttpRequestFactory(HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(2))
                .build()))
            .build();
        return HttpServiceProxyFactory.builderFor(
                RestClientAdapter.create(client))
            .build().createClient(GitHubClient.class);
    }
}
```

Cleaner than Feign for simple cases; no external dependency.

**2. RestClient — modern imperative sync:**

```java
RestClient client = RestClient.builder()
    .baseUrl("https://api.stripe.com/v1")
    .defaultHeader("Authorization", "Bearer " + apiKey)
    .build();

Charge charge = client.post()
    .uri("/charges")
    .contentType(MediaType.APPLICATION_FORM_URLENCODED)
    .body(chargeRequest)
    .retrieve()
    .onStatus(HttpStatusCode::is4xxClientError,
              (req, res) -> { throw new StripeBadRequest(res.getBody()); })
    .body(Charge.class);
```

**3. WebClient — reactive / non-blocking:**

```java
WebClient webClient = WebClient.builder()
    .baseUrl("https://api.example.com")
    .defaultHeader(HttpHeaders.ACCEPT, MediaType.APPLICATION_JSON_VALUE)
    .build();

Mono<User> userMono = webClient.get()
    .uri("/users/{id}", 42)
    .retrieve()
    .onStatus(HttpStatusCode::is5xxServerError,
              res -> Mono.error(new UpstreamException()))
    .bodyToMono(User.class)
    .timeout(Duration.ofSeconds(3));
```

Can use in Spring MVC too (just block if you must: `userMono.block()`), but if you're using `.block()` everywhere, you don't need WebClient.

**4. OpenFeign:**

```java
@FeignClient(name = "github", url = "https://api.github.com")
public interface GitHubClient {
    @GetMapping("/users/{username}")
    User getUser(@PathVariable("username") String username);
}

// With Spring Cloud load balancing:
@FeignClient(name = "payment-service")   // discovered from Eureka/Consul
public interface PaymentClient {
    @PostMapping("/charge")
    ChargeResponse charge(@RequestBody Charge c);
}
```

Feign integrates with Spring Cloud LoadBalancer, Resilience4j, Sleuth for tracing. Rich.

**5. RestTemplate (legacy):**

```java
RestTemplate rt = new RestTemplate();
User user = rt.getForObject("https://api.example.com/users/{id}", User.class, 42);
```

Simple but in maintenance. For new code, prefer RestClient or `@HttpExchange`.

// Enable Feign scanning at app startup
@SpringBootApplication
@EnableFeignClients(basePackages = "com.acme.clients")
public class Application { }

// Declarative client — no url => resolved via LoadBalancer/discovery
@FeignClient(
    name = "payment-service",
    configuration = PaymentClientConfig.class,
    fallback = PaymentClientFallback.class   // optional, used when CB opens
)
public interface PaymentClient {

    @GetMapping("/api/v1/charges/{id}")
    ChargeResponse getCharge(@PathVariable("id") String id);

    @PostMapping("/api/v1/charges")
    ChargeResponse createCharge(
        @RequestHeader("Idempotency-Key") String idemKey,
        @RequestBody ChargeRequest body
    );

    @GetMapping("/api/v1/charges")
    Page<ChargeResponse> listCharges(@SpringQueryMap ChargeFilter filter);
}

// Fallback used when the circuit breaker is open (Resilience4j)
@Component
class PaymentClientFallback implements PaymentClient {
    @Override public ChargeResponse getCharge(String id) {
        return ChargeResponse.unknown(id);
    }
    @Override public ChargeResponse createCharge(String k, ChargeRequest b) {
        throw new PaymentUnavailableException("circuit open");
    }
    @Override public Page<ChargeResponse> listCharges(ChargeFilter f) {
        return Page.empty();
    }
}

public class PaymentClientConfig {

    // 1. Auth + tracing header injection for every call
    @Bean
    RequestInterceptor authInterceptor(TokenProvider tokens) {
        return template -> {
            template.header("Authorization", "Bearer " + tokens.current());
            template.header("X-Tenant-Id", TenantContext.get());
            // traceparent is usually added automatically by Micrometer Tracing
        };
    }

    // 2. Translate 4xx/5xx into typed domain exceptions
    @Bean
    ErrorDecoder errorDecoder() {
        return (methodKey, response) -> {
            String body = readBody(response);  // copy before close!
            return switch (response.status()) {
                case 400 -> new PaymentBadRequestException(body);
                case 401, 403 -> new PaymentAuthException(body);
                case 404 -> new PaymentNotFoundException(body);
                case 409 -> new PaymentConflictException(body);   // idempotency replay
                case 429 -> new PaymentRateLimitedException(
                    response.headers().getOrDefault("Retry-After", List.of("1")).iterator().next());
                case 500, 502, 503, 504 -> new PaymentUpstreamException(body);
                default -> new PaymentUnexpectedException(response.status(), body);
            };
        };
    }

    // 3. Explicit timeouts — defaults are 10s connect / 60s read (too long!)
    @Bean
    Request.Options requestOptions() {
        return new Request.Options(
            Duration.ofMillis(1_000),  // connectTimeout
            Duration.ofMillis(2_500),  // readTimeout
            true                         // followRedirects
        );
    }

    // 4. Feign Retryer — only for idempotent calls; combine with ErrorDecoder
    //    returning feign.RetryableException for transient errors
    @Bean
    Retryer retryer() {
        return new Retryer.Default(
            100,     // initial backoff (ms)
            1_000,   // max backoff (ms)
            3        // max attempts
        );
    }

    // 5. Use Apache HttpClient 5 as the backing client (better pool than JDK default)
    @Bean
    feign.hc5.ApacheHttp5Client feignClient() {
        var cm = PoolingHttpClientConnectionManagerBuilder.create()
            .setMaxConnTotal(200)
            .setMaxConnPerRoute(50)
            .build();
        var http = HttpClients.custom().setConnectionManager(cm).build();
        return new feign.hc5.ApacheHttp5Client(http);
    }
}

@Configuration
public class PaymentWebClientConfig {

    @Bean
    ConnectionProvider paymentConnectionProvider() {
        return ConnectionProvider.builder("payment-pool")
            .maxConnections(200)
            .pendingAcquireMaxCount(400)      // queue length when pool exhausted
            .pendingAcquireTimeout(Duration.ofMillis(500))
            .maxIdleTime(Duration.ofSeconds(30))
            .maxLifeTime(Duration.ofMinutes(5))
            .evictInBackground(Duration.ofSeconds(15))
            .metrics(true)                    // exposes reactor.netty.connection.provider.*
            .build();
    }

    @Bean
    HttpClient paymentHttpClient(ConnectionProvider provider) {
        return HttpClient.create(provider)
            .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 1_000)
            .responseTimeout(Duration.ofSeconds(3))   // full response must complete
            .doOnConnected(c -> c
                .addHandlerLast(new ReadTimeoutHandler(3, TimeUnit.SECONDS))
                .addHandlerLast(new WriteTimeoutHandler(3, TimeUnit.SECONDS)))
            .compress(true)
            .followRedirect(false)
            .metrics(true, Function.identity());
    }

    @Bean
    WebClient paymentWebClient(HttpClient httpClient,
                               ObservationRegistry registry) {
        ExchangeStrategies strategies = ExchangeStrategies.builder()
            .codecs(c -> c.defaultCodecs().maxInMemorySize(1 << 20))  // 1MB
            .build();

        return WebClient.builder()
            .baseUrl("https://api.payments.internal")
            .clientConnector(new ReactorClientHttpConnector(httpClient))
            .exchangeStrategies(strategies)
            .observationRegistry(registry)          // Micrometer metrics + tracing
            .observationConvention(new DefaultClientRequestObservationConvention("payment"))
            .defaultHeader(HttpHeaders.ACCEPT, MediaType.APPLICATION_JSON_VALUE)
            .filter(authFilter())
            .filter(loggingFilter())
            .build();
    }

    private ExchangeFilterFunction authFilter() {
        return (req, next) -> next.exchange(ClientRequest.from(req)
            .header(HttpHeaders.AUTHORIZATION, "Bearer " + TokenContext.current())
            .build());
    }

    private ExchangeFilterFunction loggingFilter() {
        return ExchangeFilterFunction.ofResponseProcessor(resp -> {
            log.debug("payment <-- {} {}", resp.statusCode().value(),
                     resp.request().getURI());
            return Mono.just(resp);
        });
    }
}

@Service
public class PaymentGateway {

    private final WebClient client;

    public Mono<Charge> createCharge(ChargeRequest req) {
        return client.post()
            .uri("/v1/charges")
            .header("Idempotency-Key", req.idempotencyKey())
            .bodyValue(req)
            .retrieve()
            // Map status to typed exceptions, consuming the body
            .onStatus(HttpStatusCode::is4xxClientError, resp ->
                resp.bodyToMono(ApiError.class)
                    .defaultIfEmpty(ApiError.empty())
                    .flatMap(err -> Mono.error(switch (resp.statusCode().value()) {
                        case 400 -> new BadRequestException(err);
                        case 401, 403 -> new AuthException(err);
                        case 404 -> new NotFoundException(err);
                        case 409 -> new ConflictException(err);
                        case 429 -> new RateLimitedException(err,
                            resp.headers().firstHeader("Retry-After"));
                        default  -> new ClientErrorException(err);
                    })))
            .onStatus(HttpStatusCode::is5xxServerError, resp ->
                resp.bodyToMono(String.class)
                    .defaultIfEmpty("")
                    .flatMap(body -> Mono.error(new UpstreamException(body))))
            .bodyToMono(Charge.class)
            // Full-operation ceiling; complements responseTimeout
            .timeout(Duration.ofSeconds(4))
            // Retry only idempotent + transient — never on 4xx
            .retryWhen(Retry.backoff(3, Duration.ofMillis(100))
                .maxBackoff(Duration.ofSeconds(1))
                .jitter(0.5)
                .filter(t -> t instanceof UpstreamException
                          || t instanceof TimeoutException
                          || t instanceof ConnectException)
                .onRetryExhaustedThrow((spec, sig) -> sig.failure()))
            .transformDeferred(CircuitBreakerOperator.of(paymentCircuitBreaker))
            .contextWrite(Context.of("tenant", TenantContext.get()));
    }
}

// Server pushes many events per second — caller must not be overwhelmed
public Flux<PriceTick> streamPrices(String symbol) {
    return client.get()
        .uri("/v1/prices/stream?symbol={s}", symbol)
        .accept(MediaType.TEXT_EVENT_STREAM)
        .retrieve()
        .bodyToFlux(PriceTick.class)
        // Backpressure knobs
        .limitRate(64)                              // prefetch 64, request more as consumed
        .onBackpressureBuffer(1_000,                // cap in-memory buffer
            dropped -> meter.counter("ticks.dropped").increment(),
            BufferOverflowStrategy.DROP_OLDEST)
        .timeout(Duration.ofSeconds(30))            // abort if silent too long
        .doOnCancel(() -> log.info("client cancelled price stream for {}", symbol));
}

// NDJSON bulk export — bounded parallelism downstream
public Flux<EnrichedRow> enrichExport() {
    return client.get().uri("/v1/export.ndjson").retrieve()
        .bodyToFlux(RawRow.class)
        .limitRate(256)
        .flatMap(this::enrichAsync, 8)              // 8 concurrent downstream calls
        .onErrorResume(t -> {
            log.error("export failed", t);
            return Flux.empty();
        });
}
